/// How many terminal columns a printed scalar advances the cursor.
/// (Waycar patch: client screen model.)
///
/// mosh-server lays out its screen with the Host's `wcwidth`, and its
/// diffs skip the cells it believes did not change, so `MoshScreen` must
/// advance the cursor exactly as the Host does or every cell after a
/// disagreement lands off by a column (2 extra columns for each 👁 in an
/// omp status row autowrapped the model and drifted every later row, #148).
///
/// - Wide (2): `MoshCharacterWidthTable.wide`, generated by
///   `Scripts/generate-character-widths.swift` from Darwin's `wcwidth`
///   (`MoshCharacterWidthTable.sourceDescription`: en_US.UTF-8, Unicode
///   15.0, macOS 27.0.1, 26A434). Text-presentation symbols such as U+1F441
///   👁 and the regional indicators are 1, as Darwin says.
/// - Zero (0): general category Mn/Me/Cf (except U+00AD SOFT HYPHEN),
///   Zl/Zp (U+2028, U+2029), U+200B and U+1160–11FF, as Darwin gives
///   (U+FE0E/FE0F and U+200D included).
/// - Darwin also zeroes Mc spacing marks; this function gives them 1.
///
/// A glibc Host differs (source review of glibc's
/// `localedata/unicode-gen/utf8_gen.py`, HEAD, 2026-10-07):
/// - U+3248–324F and U+4DC0–4DFF are 2 there (1 on Darwin).
/// - Unicode-version gaps: glibc 2.35 treats Unicode 15 emoji as
///   unassigned (-1), which mosh-server ignores; 2.39 counts U+2FFC–2FFF
///   and U+31EF as wide (unassigned on Darwin's Unicode 15.0).
/// - glibc zeroes by Default_Ignorable_Code_Point, not by Cf, so its
///   Prepended_Concatenation_Mark Cf scalars (U+0600–0605, U+06DD, U+110BD
///   …) are 1, and default-ignorable letters such as U+3164 and U+FFA0 are 0.
/// - glibc zeroes Hangul V/T jamo by HangulSyllableType, which adds
///   U+D7B0–D7FB to U+1160–11FF.
/// - Mc spacing marks are 1 on glibc, as here.
enum MoshCharacterWidth {
    /// 0 for combining and format scalars (they join the previous cell),
    /// 2 for wide scalars, 1 otherwise. Controls never reach here: the
    /// parser handles them.
    static func columns(of scalar: Unicode.Scalar) -> Int {
        let value = scalar.value
        if value < 0x300 {
            // Latin-1 and friends; U+00AD SOFT HYPHEN is Cf but prints.
            return 1
        }
        if value == 0x200B || (0x1160...0x11FF).contains(value) {
            return 0
        }
        switch scalar.properties.generalCategory {
        case .nonspacingMark, .enclosingMark, .format, .lineSeparator, .paragraphSeparator:
            return 0
        default:
            break
        }
        return isWide(value) ? 2 : 1
    }

    /// Binary search over the sorted, disjoint generated ranges.
    static func isWide(_ value: UInt32) -> Bool {
        let ranges = MoshCharacterWidthTable.wide
        var low = 0
        var high = ranges.count
        while low < high {
            let mid = (low + high) / 2
            if ranges[mid].upperBound < value {
                low = mid + 1
            } else {
                high = mid
            }
        }
        return low < ranges.count && ranges[low].contains(value)
    }
}
